ruleHooks.extraMethods:
; Gravar Componentes do Checklist (acoplado S/N por componente da engenharia)
;
; set sc=$$GravarComponentesChecklist^WDOMTESTEROM100ATAB2ARG(codEmpresa,codChecklist,codEngenharia,term)
GravarComponentesChecklist(codEmpresa,codChecklist,codEngenharia,term)	;
$$$VAR
new codSequencia,linha,dados,dataHora,codOperador
;
if $get(codEngenharia)="" quit $$$ERROR(10000,"Engenharia não informada!")
;
set dataHora=$$$horologEmp(codEmpresa)
set codOperador=$$VEROP^%CSUTIUD(1)
;
do $$$KillG(^WDOMTESTEROMC(1,codEmpresa,1,codChecklist,4,codEngenharia))
;
set codSequencia=""
for  set codSequencia=$order(^mtempWDOMTESTEROM100ATAB2A(term,codSequencia)) quit:codSequencia=""  do
. set linha=$get(^mtempWDOMTESTEROM100ATAB2A(term,codSequencia))
. set dados=dataHora_Z_codOperador_Z_codSequencia_Z_$piece(linha,Z,6)
. do $$$SetG(^WDOMTESTEROMC(1,codEmpresa,1,codChecklist,4,codEngenharia,$piece(linha,Z,2)),dados)
;
quit $$$OK
;
; Obter Descrição da Engenharia
;
; set descricao=$$ObterDescricaoEngenharia^WDOMTESTEROM100ATAB2ARG(codEmpresa,codEngenharia)
ObterDescricaoEngenharia(codEmpresa,codEngenharia)	;
$$$VAR
new sc,codEditado,descricao,unidade
;
if $get(codEngenharia)="" quit ""
set (codEditado,descricao,unidade)=""
set sc=$$ObterDescEngItem^CCPMERG001(codEmpresa,codEngenharia,.codEditado,.descricao,.unidade)
;
quit $select(codEditado'="":codEditado_" - ",1:"")_descricao
